
insert into public.intelligence_data_sources(slug,channel,name,logo_url,website_url,description,market_codes,languages,status,sort_order)
select x.slug,x.channel,x.name,x.logo_url,x.website_url,x.description,
 array(select jsonb_array_elements_text(x.market_codes)),array(select jsonb_array_elements_text(x.languages)),x.status,x.sort_order
from jsonb_to_recordset($json$[{"slug":"amazon","channel":"电商平台","name":"Amazon","logo_url":"https://cdn.simpleicons.org/amazon","website_url":"https://www.amazon.com","description":"全球综合电商商品、价格、榜单与评论信号。","market_codes":["US","CA","GB","DE","FR","IT","ES","JP","AU","IN"],"languages":["en","ja","de","fr","es"],"status":"needs_auth","sort_order":1},{"slug":"ebay","channel":"电商平台","name":"eBay","logo_url":"https://cdn.simpleicons.org/ebay","website_url":"https://www.ebay.com","description":"商品列表、价格与受权限约束的成交历史。","market_codes":["US","GB","DE","AU","CA"],"languages":["en","de"],"status":"limited","sort_order":2},{"slug":"aliexpress","channel":"电商平台","name":"AliExpress","logo_url":"https://cdn.simpleicons.org/aliexpress","website_url":"https://www.aliexpress.com","description":"跨境商品、价格与评价信号。","market_codes":["US","GB","DE","FR","ES","JP"],"languages":["en","es","fr","de"],"status":"planned","sort_order":3},{"slug":"walmart","channel":"电商平台","name":"Walmart","logo_url":"https://cdn.simpleicons.org/walmart","website_url":"https://www.walmart.com","description":"美国零售商品、价格与评分信号。","market_codes":["US"],"languages":["en"],"status":"planned","sort_order":4},{"slug":"shopee","channel":"电商平台","name":"Shopee","logo_url":"https://cdn.simpleicons.org/shopee","website_url":"https://shopee.com","description":"东南亚及部分区域电商商品信号。","market_codes":["SG","MY","TH","VN","ID","PH","TW","BR"],"languages":["en","th","vi","id","ms","zh"],"status":"planned","sort_order":5},{"slug":"lazada","channel":"电商平台","name":"Lazada","logo_url":"https://cdn.simpleicons.org/lazada","website_url":"https://www.lazada.com","description":"东南亚电商商品、价格与评论信号。","market_codes":["SG","MY","TH","VN","ID","PH"],"languages":["en","th","vi","id","ms"],"status":"planned","sort_order":6},{"slug":"google-trends","channel":"搜索引擎","name":"Google Trends","logo_url":"https://cdn.simpleicons.org/google","website_url":"https://trends.google.com","description":"关键词相对搜索兴趣、地区热度与相关查询。","market_codes":["GLOBAL","US","JP","DE","GB","FR","CA","AU"],"languages":["en","ja","de","fr"],"status":"needs_auth","sort_order":7},{"slug":"google-search","channel":"搜索引擎","name":"Google Search","logo_url":"https://cdn.simpleicons.org/google","website_url":"https://www.google.com","description":"SERP、竞品域名、商品页面与内容线索。","market_codes":["GLOBAL"],"languages":["en","ja","de","fr","es","zh"],"status":"planned","sort_order":8},{"slug":"bing","channel":"搜索引擎","name":"Bing","logo_url":"https://cdn.simpleicons.org/bing","website_url":"https://www.bing.com","description":"网页搜索结果与内容发现。","market_codes":["GLOBAL"],"languages":["en"],"status":"planned","sort_order":9},{"slug":"tiktok","channel":"社交媒体","name":"TikTok","logo_url":"https://cdn.simpleicons.org/tiktok","website_url":"https://www.tiktok.com","description":"公开视频、话题、互动量与增长信号。","market_codes":["US","GB","DE","FR","JP","KR","SG","TH","ID"],"languages":["en","ja","de","fr","ko","th","id"],"status":"planned","sort_order":10},{"slug":"instagram","channel":"社交媒体","name":"Instagram","logo_url":"https://cdn.simpleicons.org/instagram","website_url":"https://www.instagram.com","description":"公开帖子、标签、创作者与互动信号。","market_codes":["GLOBAL"],"languages":["en","ja","de","fr","es"],"status":"planned","sort_order":11},{"slug":"facebook","channel":"社交媒体","name":"Facebook","logo_url":"https://cdn.simpleicons.org/facebook","website_url":"https://www.facebook.com","description":"公开页面、帖子与互动信号，受权限限制。","market_codes":["GLOBAL"],"languages":["en"],"status":"planned","sort_order":12},{"slug":"youtube","channel":"视频平台","name":"YouTube","logo_url":"https://cdn.simpleicons.org/youtube","website_url":"https://www.youtube.com","description":"视频、频道、播放量、评论与测评内容。","market_codes":["GLOBAL"],"languages":["en","ja","de","fr","es","zh"],"status":"needs_auth","sort_order":13},{"slug":"reddit","channel":"社区论坛","name":"Reddit","logo_url":"https://cdn.simpleicons.org/reddit","website_url":"https://www.reddit.com","description":"社区讨论、购买意图、产品痛点与口碑。","market_codes":["US","GB","CA","AU","DE"],"languages":["en","de"],"status":"needs_auth","sort_order":14},{"slug":"trustpilot","channel":"用户评价","name":"Trustpilot","logo_url":"https://cdn.simpleicons.org/trustpilot","website_url":"https://www.trustpilot.com","description":"品牌与零售商评价、评分和口碑趋势。","market_codes":["GLOBAL"],"languages":["en","de","fr","es"],"status":"planned","sort_order":15},{"slug":"x","channel":"社交媒体","name":"X","logo_url":"https://cdn.simpleicons.org/x","website_url":"https://x.com","description":"公开讨论、话题与传播互动信号。","market_codes":["GLOBAL"],"languages":["en","ja"],"status":"planned","sort_order":16}]$json$::jsonb) as x(slug text,channel text,name text,logo_url text,website_url text,description text,market_codes jsonb,languages jsonb,status text,sort_order integer)
on conflict(slug) do update set channel=excluded.channel,name=excluded.name,logo_url=excluded.logo_url,website_url=excluded.website_url,description=excluded.description,market_codes=excluded.market_codes,languages=excluded.languages,status=excluded.status,sort_order=excluded.sort_order,is_active=true,updated_at=now();

insert into public.intelligence_source_connectors(source_id,name,connector_type,provider,actor_id,status,auth_required,capabilities,notes)
select s.id,x.name,x.connector_type,x.provider,x.actor_id,x.status,x.auth_required,
 array(select jsonb_array_elements_text(x.capabilities)),x.notes
from jsonb_to_recordset($json$[{"slug":"amazon","name":"官方 API","connector_type":"official_api","provider":"Amazon SP-API","actor_id":null,"status":"needs_auth","auth_required":true,"capabilities":["product_listing","price","seller","reviews"],"notes":"卖家授权数据；不能获取全市场竞品真实销量。"},{"slug":"amazon","name":"公开商品采集","connector_type":"apify_actor","provider":"Amazon 商品页 Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["product_listing","price","bsr","reviews"],"notes":"Actor ID 待选型验证。"},{"slug":"ebay","name":"官方 API","connector_type":"official_api","provider":"eBay Browse API","actor_id":null,"status":"needs_auth","auth_required":true,"capabilities":["product_listing","price"],"notes":"需要开发者应用凭证。"},{"slug":"ebay","name":"成交历史接口","connector_type":"official_api","provider":"Marketplace Insights API","actor_id":null,"status":"limited","auth_required":true,"capabilities":["sold_history"],"notes":"Limited Release，访问资格受限。"},{"slug":"aliexpress","name":"商品采集","connector_type":"apify_actor","provider":"AliExpress 商品 Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["product_listing","price","reviews"],"notes":"Actor ID 待选型验证。"},{"slug":"walmart","name":"商品采集","connector_type":"apify_actor","provider":"Walmart 商品 Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["product_listing","price","reviews"],"notes":"Actor ID 待选型验证。"},{"slug":"shopee","name":"商品采集","connector_type":"apify_actor","provider":"Shopee 商品 Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["product_listing","price","reviews"],"notes":"Actor ID 待选型验证。"},{"slug":"lazada","name":"商品采集","connector_type":"apify_actor","provider":"Lazada 商品 Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["product_listing","price","reviews"],"notes":"Actor ID 待选型验证。"},{"slug":"google-trends","name":"Apify Actor","connector_type":"apify_actor","provider":"surefetch/google-trends","actor_id":"surefetch/google-trends","status":"needs_auth","auth_required":true,"capabilities":["search_interest","geo_interest","related_queries","seasonality"],"notes":"已规划复用该 Actor；仍需 Apify Token 与输入输出验证。"},{"slug":"google-search","name":"SERP Actor","connector_type":"apify_actor","provider":"Google Search Results Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["serp","competitor_domains","shopping_results"],"notes":"Actor ID 与字段映射待配置。"},{"slug":"bing","name":"搜索采集","connector_type":"apify_actor","provider":"Bing Search Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["serp"],"notes":"Actor ID 待配置。"},{"slug":"tiktok","name":"公开内容采集","connector_type":"apify_actor","provider":"TikTok 内容 Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["video_count","views","engagement","hashtags","comments"],"notes":"遵守平台条款与地区限制。"},{"slug":"instagram","name":"公开内容采集","connector_type":"apify_actor","provider":"Instagram 公共内容 Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["posts","engagement","hashtags"],"notes":"仅限允许访问的公开数据。"},{"slug":"facebook","name":"官方 API","connector_type":"official_api","provider":"Meta Graph API","actor_id":null,"status":"needs_auth","auth_required":true,"capabilities":["public_pages","posts","engagement"],"notes":"需要应用审核与相应权限。"},{"slug":"youtube","name":"官方 API","connector_type":"official_api","provider":"YouTube Data API v3","actor_id":null,"status":"needs_auth","auth_required":true,"capabilities":["videos","views","comments","channels"],"notes":"需要 Google Cloud API Key，受配额限制。"},{"slug":"reddit","name":"官方 API","connector_type":"official_api","provider":"Reddit API","actor_id":null,"status":"needs_auth","auth_required":true,"capabilities":["discussions","comments","community_signals"],"notes":"需要 OAuth 应用并遵守 API 条款。"},{"slug":"trustpilot","name":"评价采集","connector_type":"apify_actor","provider":"Trustpilot Reviews Actor","actor_id":null,"status":"planned","auth_required":true,"capabilities":["reviews","rating","sentiment"],"notes":"Actor ID 待选型验证。"},{"slug":"x","name":"官方 API","connector_type":"official_api","provider":"X API","actor_id":null,"status":"needs_auth","auth_required":true,"capabilities":["posts","engagement","topics"],"notes":"取决于 API 套餐与权限。"}]$json$::jsonb) as x(slug text,name text,connector_type text,provider text,actor_id text,status text,auth_required boolean,capabilities jsonb,notes text)
join public.intelligence_data_sources s on s.slug=x.slug
on conflict(source_id,name) do update set connector_type=excluded.connector_type,provider=excluded.provider,actor_id=excluded.actor_id,status=excluded.status,auth_required=excluded.auth_required,capabilities=excluded.capabilities,notes=excluded.notes,updated_at=now();

insert into public.intelligence_source_capabilities(source_id,capability_key,label,description,evidence_type,availability_status,metric_keys)
select s.id,x.capability_key,x.label,x.description,x.evidence_type,s.status,
 array[x.capability_key]
from jsonb_to_recordset($json$[{"slug":"amazon","capability_key":"product_listing","label":"商品信息","description":"商品标题、型号、类目与商品链接","evidence_type":"observed"},{"slug":"amazon","capability_key":"price","label":"价格与促销","description":"当前价格、折扣与价格变化","evidence_type":"observed"},{"slug":"amazon","capability_key":"bsr","label":"商品排名","description":"Best Sellers Rank 等平台排名信号","evidence_type":"observed"},{"slug":"amazon","capability_key":"reviews","label":"评论与评分","description":"评论数量、评分与评论文本","evidence_type":"observed"},{"slug":"amazon","capability_key":"seller","label":"卖家信息","description":"卖家与品牌信息","evidence_type":"observed"},{"slug":"amazon","capability_key":"estimated_sales","label":"销量估算","description":"第三方估算，不等于真实销量","evidence_type":"estimated"},{"slug":"ebay","capability_key":"product_listing","label":"商品信息","description":"商品标题、类目与商品链接","evidence_type":"observed"},{"slug":"ebay","capability_key":"price","label":"价格","description":"商品挂牌价格","evidence_type":"observed"},{"slug":"ebay","capability_key":"sold_history","label":"成交历史","description":"受限接口提供的历史成交记录","evidence_type":"observed"},{"slug":"aliexpress","capability_key":"product_listing","label":"商品信息","description":"商品标题、型号与类目","evidence_type":"observed"},{"slug":"aliexpress","capability_key":"price","label":"价格与促销","description":"商品价格与折扣","evidence_type":"observed"},{"slug":"aliexpress","capability_key":"reviews","label":"评论与评分","description":"评论数量、评分与评价内容","evidence_type":"observed"},{"slug":"walmart","capability_key":"product_listing","label":"商品信息","description":"商品标题与类目","evidence_type":"observed"},{"slug":"walmart","capability_key":"price","label":"价格","description":"商品价格与促销","evidence_type":"observed"},{"slug":"walmart","capability_key":"reviews","label":"评论与评分","description":"商品评分与评论","evidence_type":"observed"},{"slug":"shopee","capability_key":"product_listing","label":"商品信息","description":"商品标题、店铺与类目","evidence_type":"observed"},{"slug":"shopee","capability_key":"price","label":"价格","description":"商品价格与促销","evidence_type":"observed"},{"slug":"shopee","capability_key":"reviews","label":"评论与评分","description":"商品评论与评分","evidence_type":"observed"},{"slug":"lazada","capability_key":"product_listing","label":"商品信息","description":"商品标题、店铺与类目","evidence_type":"observed"},{"slug":"lazada","capability_key":"price","label":"价格","description":"商品价格与促销","evidence_type":"observed"},{"slug":"lazada","capability_key":"reviews","label":"评论与评分","description":"商品评论与评分","evidence_type":"observed"},{"slug":"google-trends","capability_key":"search_interest","label":"搜索兴趣","description":"关键词相对搜索热度指数","evidence_type":"observed"},{"slug":"google-trends","capability_key":"geo_interest","label":"地区热度","description":"不同国家地区的相对兴趣","evidence_type":"observed"},{"slug":"google-trends","capability_key":"related_queries","label":"相关查询","description":"上升查询与相关关键词","evidence_type":"observed"},{"slug":"google-trends","capability_key":"seasonality","label":"季节性","description":"周期性需求与季节变化","evidence_type":"inferred"},{"slug":"google-search","capability_key":"serp","label":"搜索结果","description":"自然搜索结果与页面信息","evidence_type":"observed"},{"slug":"google-search","capability_key":"competitor_domains","label":"竞品网站","description":"品牌官网与竞品域名线索","evidence_type":"observed"},{"slug":"google-search","capability_key":"shopping_results","label":"购物结果","description":"商品价格与商家信息（视地区可用性）","evidence_type":"observed"},{"slug":"bing","capability_key":"serp","label":"搜索结果","description":"网页搜索结果与内容线索","evidence_type":"observed"},{"slug":"tiktok","capability_key":"video_count","label":"视频数量","description":"关键词或话题相关公开视频数量","evidence_type":"observed"},{"slug":"tiktok","capability_key":"views","label":"播放量","description":"视频播放量（如可见）","evidence_type":"observed"},{"slug":"tiktok","capability_key":"engagement","label":"互动表现","description":"点赞、评论、分享等互动信号","evidence_type":"observed"},{"slug":"tiktok","capability_key":"hashtags","label":"热门话题","description":"相关话题与标签","evidence_type":"observed"},{"slug":"tiktok","capability_key":"comments","label":"用户评论","description":"公开视频评论与需求表达","evidence_type":"observed"},{"slug":"instagram","capability_key":"posts","label":"公开帖子","description":"公开帖子与标签","evidence_type":"observed"},{"slug":"instagram","capability_key":"engagement","label":"互动表现","description":"点赞与评论等互动信号","evidence_type":"observed"},{"slug":"instagram","capability_key":"hashtags","label":"热门话题","description":"公开标签与内容主题","evidence_type":"observed"},{"slug":"facebook","capability_key":"public_pages","label":"公开主页","description":"公开品牌主页信息","evidence_type":"observed"},{"slug":"facebook","capability_key":"posts","label":"公开帖子","description":"允许访问的公开帖子","evidence_type":"observed"},{"slug":"facebook","capability_key":"engagement","label":"互动表现","description":"公开互动指标","evidence_type":"observed"},{"slug":"youtube","capability_key":"videos","label":"视频内容","description":"视频标题、描述与发布时间","evidence_type":"observed"},{"slug":"youtube","capability_key":"views","label":"播放量","description":"视频播放量与增长信号","evidence_type":"observed"},{"slug":"youtube","capability_key":"comments","label":"评论","description":"公开视频评论与用户反馈","evidence_type":"observed"},{"slug":"youtube","capability_key":"channels","label":"频道","description":"创作者与频道信息","evidence_type":"observed"},{"slug":"reddit","capability_key":"discussions","label":"社区讨论","description":"相关社区讨论与帖子","evidence_type":"observed"},{"slug":"reddit","capability_key":"comments","label":"用户评论","description":"评论、赞同与反对信号","evidence_type":"observed"},{"slug":"reddit","capability_key":"community_signals","label":"需求与痛点","description":"购买意图、未满足需求与使用痛点","evidence_type":"inferred"},{"slug":"trustpilot","capability_key":"reviews","label":"用户评价","description":"品牌与零售商评论","evidence_type":"observed"},{"slug":"trustpilot","capability_key":"rating","label":"评分","description":"评分分布与变化","evidence_type":"observed"},{"slug":"trustpilot","capability_key":"sentiment","label":"情感倾向","description":"评论情绪与主题归纳","evidence_type":"inferred"},{"slug":"x","capability_key":"posts","label":"公开帖子","description":"公开帖子与讨论","evidence_type":"observed"},{"slug":"x","capability_key":"engagement","label":"互动表现","description":"公开互动信号","evidence_type":"observed"},{"slug":"x","capability_key":"topics","label":"话题趋势","description":"热门话题与讨论增速","evidence_type":"observed"}]$json$::jsonb) as x(slug text,capability_key text,label text,description text,evidence_type text)
join public.intelligence_data_sources s on s.slug=x.slug
on conflict(source_id,capability_key) do update set label=excluded.label,description=excluded.description,evidence_type=excluded.evidence_type,availability_status=excluded.availability_status,metric_keys=excluded.metric_keys;

insert into public.intelligence_demo_datasets(organization_id,slug,name,product_label,is_demo,dataset)
select id,'wireless-headphones-global-demo-v1','全球无线降噪耳机市场演示数据','AI 主动降噪无线耳机',true,$json${"demo_notice":"以下全部为演示模拟数据，用于展示图表与分析交互，不代表真实平台销量、搜索量或 API/Actor 采集结果。","product":{"name":"AI 主动降噪无线耳机","category":"音频设备","brand":"Auralink（虚构演示品牌）"},"kpis":[{"label":"跨平台商品样本","value":"2,486","delta":"+18.6%","unit":"条"},{"label":"搜索兴趣指数","value":"76.4","delta":"+12.8%","unit":"/100"},{"label":"社交互动样本","value":"184K","delta":"+24.3%","unit":"次"},{"label":"消费者评价样本","value":"12,840","delta":"+9.7%","unit":"条"}],"trend":[{"period":"06月","search":42,"social":31,"commerce":36},{"period":"07月","search":48,"social":38,"commerce":40},{"period":"08月","search":51,"social":44,"commerce":46},{"period":"09月","search":58,"social":52,"commerce":51},{"period":"10月","search":67,"social":64,"commerce":59},{"period":"11月","search":76,"social":78,"commerce":72}],"bestsellers":[{"rank":1,"name":"QuietMax Pro ANC","brand":"SoundPeak","price":129.99,"currency":"USD","score":94,"review_count":8420,"market":"US"},{"rank":2,"name":"AirSilence 5","brand":"Auralink Demo","price":99.99,"currency":"USD","score":89,"review_count":6210,"market":"JP"},{"rank":3,"name":"Studio ANC X","brand":"NovaSound","price":159,"currency":"USD","score":86,"review_count":5340,"market":"DE"},{"rank":4,"name":"TravelBuds NC","brand":"Waveform","price":79.99,"currency":"USD","score":81,"review_count":4980,"market":"GB"},{"rank":5,"name":"Hybrid Quiet 2","brand":"EchoLab","price":119,"currency":"USD","score":78,"review_count":3720,"market":"CA"}],"search_terms":[{"term":"best noise cancelling headphones","index":100,"growth":"+28%"},{"term":"hybrid ANC earbuds","index":82,"growth":"+36%"},{"term":"long battery headphones","index":71,"growth":"+19%"},{"term":"low latency wireless audio","index":58,"growth":"+42%"},{"term":"travel noise cancelling","index":54,"growth":"+17%"}],"social":[{"platform":"TikTok","engagement":82,"share":38},{"platform":"YouTube","engagement":64,"share":29},{"platform":"Instagram","engagement":42,"share":19},{"platform":"Reddit","engagement":31,"share":14}],"pain_points":[{"label":"佩戴舒适度 / 耳压","count":2860},{"label":"通话降噪效果","count":2180},{"label":"续航与充电","count":1840},{"label":"多设备切换","count":1420},{"label":"风噪控制","count":980}],"competitors":[{"name":"SoundPeak","share":28,"price":129.99},{"name":"NovaSound","share":22,"price":159},{"name":"Auralink Demo","share":18,"price":99.99},{"name":"Waveform","share":17,"price":79.99},{"name":"EchoLab","share":15,"price":119}],"categories":[{"label":"头戴式 ANC","value":42},{"label":"真无线 ANC","value":34},{"label":"运动降噪耳机","value":14},{"label":"开放式音频","value":10}],"markets":[{"code":"US","name":"美国","flag":"🇺🇸","opportunity":92,"search":86,"social":88,"price":139},{"code":"JP","name":"日本","flag":"🇯🇵","opportunity":89,"search":82,"social":76,"price":158},{"code":"DE","name":"德国","flag":"🇩🇪","opportunity":84,"search":78,"social":72,"price":146},{"code":"GB","name":"英国","flag":"🇬🇧","opportunity":81,"search":74,"social":80,"price":132},{"code":"CA","name":"加拿大","flag":"🇨🇦","opportunity":77,"search":69,"social":71,"price":135},{"code":"AU","name":"澳大利亚","flag":"🇦🇺","opportunity":74,"search":66,"social":73,"price":142},{"code":"KR","name":"韩国","flag":"🇰🇷","opportunity":72,"search":70,"social":79,"price":151},{"code":"FR","name":"法国","flag":"🇫🇷","opportunity":68,"search":63,"social":65,"price":128}],"ai_reports":{"all":"综合判断：演示样本显示，AI 主动降噪无线耳机在美国、日本和德国具备较高的需求与渠道热度信号。搜索兴趣、社交互动和电商样本同步上升，值得进一步验证中高端 ANC 细分市场。建议优先验证 99–159 美元价格带，并围绕佩戴舒适度、通话降噪和多设备切换形成差异化。注意：以上为模拟数据推演，不可作为真实市场规模或销量结论。","tabs":{"overview":"情报总览专项解读：搜索、社交和电商信号在近六个月呈同步上升。多源同向变化值得继续观察，但仍需要真实采集和连续时间序列验证。","bestsellers":"热销榜专项解读：头部商品的演示热度分数集中在 78–94。高评分与评论样本量可作为商品关注度线索，但不能直接推断真实销量。","search":"搜索趋势专项解读：混合 ANC、低延迟和长续航相关查询增长较快。搜索指数是相对兴趣信号，不是绝对搜索量。","social":"社交趋势专项解读：TikTok 与 YouTube 在演示互动样本中占比较高。适合验证短视频演示、降噪对比和真实通话场景内容。","consumer":"消费者洞察专项解读：佩戴舒适度、通话降噪和续航是高频痛点。建议将耳压、麦克风阵列、风噪抑制和快充作为产品验证重点。","competitors":"竞品专项解读：头部品牌价格分布约 80–159 美元。Auralink Demo 处于中端区间，需以佩戴舒适度和通话质量形成差异化。","categories":"品类专项解读：头戴式 ANC 与真无线 ANC 合计占演示样本结构的 76%。","markets":"国家市场专项解读：美国、日本、德国的演示机会指数领先。实际进入顺序仍需结合当地法规、渠道成本、竞争强度和真实数据验证。"}}}$json$::jsonb
from public.organizations order by created_at limit 1
on conflict(organization_id,slug) do update set name=excluded.name,product_label=excluded.product_label,is_demo=true,dataset=excluded.dataset,updated_at=now();
